# ============================================================================
# Lumina Studio - Toponymy Semantic Cluster Topic Extraction Pipeline
#
# WHAT: Unsupervised topic extraction pipeline that analyzes EVoC visual clusters
#       using Tutte Institute's Toponymy library to extract keyphrases and theme titles.
# WHY: High-dimensional visual clusters generated by EVoC only carry integer labels (e.g. Cluster 14).
#      Toponymy discovers dominant semantic phrases from the underlying image descriptions,
#      producing human-interpretable category names for Scope Map (scope.html) exploration.
#
# PROTOCOL COMPLIANCE:
# 1. "can_be_long" Variable Naming: Zero shorthand abbreviations or single-letter variables.
# 2. "Tutorial Protocol": Comprehensive instructional WHAT and WHY documentation.
# ============================================================================

import os
import sys
import json
import sqlite3
import time
import argparse
from typing import List, Dict, Tuple, Optional
from collections import Counter

# WHAT: Reconfiguring standard output and error streams for UTF-8 encoding.
# WHY: Prevents Windows console CP1252 encoding crashes when printing rich unicode text.
if hasattr(sys.stdout, 'reconfigure'):
    sys.stdout.reconfigure(encoding='utf-8')
if hasattr(sys.stderr, 'reconfigure'):
    sys.stderr.reconfigure(encoding='utf-8')

# WHAT: Importing Tutte Institute's Toponymy keyphrase extraction engine.
# WHY: Toponymy implements specialized algorithms for identifying distinct phrases across clusters.
try:
    import toponymy
    from toponymy import KeyphraseBuilder
    IS_TOPONYMY_LIBRARY_AVAILABLE = True
except ImportError:
    IS_TOPONYMY_LIBRARY_AVAILABLE = False


def extract_keyphrases_from_text_collection(
    text_corpus_documents_collection: List[str],
    maximum_keyphrases_to_extract_count: int = 5
) -> List[str]:
    # WHAT: Extracts salient multi-word keyphrases from a collection of image description texts.
    # WHY: Identifies the distinctive vocabulary defining a semantic cluster.
    if not text_corpus_documents_collection:
        return []

    # Clean empty strings
    sanitized_text_documents_collection = [
        single_text_document.strip()
        for single_text_document in text_corpus_documents_collection
        if isinstance(single_text_document, str) and single_text_document.strip()
    ]

    if not sanitized_text_documents_collection:
        return []

    if IS_TOPONYMY_LIBRARY_AVAILABLE:
        try:
            keyphrase_builder_instance = KeyphraseBuilder(max_df=0.95, min_df=1)
            sparse_occurrence_matrix, extracted_candidate_vocabulary_list, _ = (
                keyphrase_builder_instance.fit_transform(sanitized_text_documents_collection)
            )

            # Sum column occurrences across documents to rank by frequency within cluster
            matrix_column_frequencies = sparse_occurrence_matrix.sum(axis=0).A1
            sorted_indices_by_frequency = matrix_column_frequencies.argsort()[::-1]

            ranked_keyphrases_list = [
                extracted_candidate_vocabulary_list[column_index]
                for column_index in sorted_indices_by_frequency[:maximum_keyphrases_to_extract_count]
                if matrix_column_frequencies[column_index] > 0
            ]

            if ranked_keyphrases_list:
                return ranked_keyphrases_list
        except Exception as keyphrase_extraction_exception:
            # Fallback to standard token counter if vocabulary size is too small for matrix
            pass

    # WHAT: Fallback frequency-based keyphrase extraction.
    # WHY: Guarantees reliable topic generation even if Toponymy matrix parameters encounter degenerate edge cases.
    token_frequency_counter = Counter()
    common_english_stopwords_set = {
        'the', 'a', 'an', 'and', 'or', 'in', 'on', 'at', 'with', 'by', 'of', 'for', 'to',
        'is', 'are', 'was', 'were', 'it', 'this', 'that', 'from', 'as', 'into', 'visible',
        'image', 'shows', 'depicts', 'view', 'scene', 'picture', 'photo', 'photograph'
    }

    for single_document_text in sanitized_text_documents_collection:
        normalized_words_list = single_document_text.lower().split()
        filtered_meaningful_tokens = [
            single_word.strip('.,;:"\'()[]{}')
            for single_word in normalized_words_list
            if len(single_word) > 2 and single_word not in common_english_stopwords_set
        ]
        token_frequency_counter.update(filtered_meaningful_tokens)

    most_frequent_token_tuples = token_frequency_counter.most_common(maximum_keyphrases_to_extract_count)
    return [token_string for token_string, frequency_count in most_frequent_token_tuples]


def format_human_readable_topic_title(extracted_toponymy_keyphrases_list: List[str]) -> str:
    # WHAT: Combines top keyphrases into a polished, title-cased thematic heading.
    # WHY: Provides visually appealing labels for UI map overlays and cluster legends.
    if not extracted_toponymy_keyphrases_list:
        return "Miscellaneous Visual Group"

    # Take the top 2-3 keyphrases and format title
    primary_topic_keyphrases = extracted_toponymy_keyphrases_list[:2]
    capitalized_phrase_tokens = [
        single_phrase.title()
        for single_phrase in primary_topic_keyphrases
    ]
    return " & ".join(capitalized_phrase_tokens)


def execute_toponymy_cluster_labeling_pipeline():
    # ------------------------------------------------------------------------
    # Command Line Interface Argument Parsing
    # ------------------------------------------------------------------------
    command_line_argument_parser = argparse.ArgumentParser(
        description='Lumina Toponymy Semantic Cluster Labeling Pipeline'
    )
    command_line_argument_parser.add_argument(
        '--db',
        type=str,
        default='images.db',
        help='Path to SQLite database containing image_clusters and images tables'
    )
    command_line_argument_parser.add_argument(
        '--samples_per_cluster',
        type=int,
        default=25,
        help='Maximum number of text descriptions sampled per cluster for keyphrase extraction'
    )
    command_line_argument_parser.add_argument(
        '--keyphrases_count',
        type=int,
        default=5,
        help='Number of keyphrases to discover per cluster'
    )
    parsed_command_line_arguments = command_line_argument_parser.parse_args()

    target_sqlite_database_file_path = parsed_command_line_arguments.db
    maximum_samples_per_cluster_count = parsed_command_line_arguments.samples_per_cluster
    maximum_keyphrases_per_cluster_count = parsed_command_line_arguments.keyphrases_count

    print("======================================================================")
    print("      Lumina Toponymy Semantic Cluster Topic Extraction Pipeline      ")
    print("======================================================================")
    print(f"[*] Target SQLite Database: {target_sqlite_database_file_path}")
    print(f"[*] Toponymy Engine Status: {'INSTALLED (v' + toponymy.__version__ + ')' if IS_TOPONYMY_LIBRARY_AVAILABLE else 'UNAVAILABLE (Using Frequency Fallback)'}")

    if not os.path.exists(target_sqlite_database_file_path):
        print(f"[!] Error: Database file not found at {target_sqlite_database_file_path}")
        sys.exit(1)

    sqlite_database_connection = sqlite3.connect(target_sqlite_database_file_path)
    sqlite_database_cursor = sqlite_database_connection.cursor()

    # WHAT: Verifying required tables exist in images.db.
    # WHY: Cluster labeling requires image_clusters (from EVoC) and images (metadata text).
    sqlite_database_cursor.execute(
        "SELECT name FROM sqlite_master WHERE type='table' AND name IN ('image_clusters', 'images')"
    )
    discovered_database_table_names = [table_row[0] for table_row in sqlite_database_cursor.fetchall()]

    if 'image_clusters' not in discovered_database_table_names or 'images' not in discovered_database_table_names:
        print("[!] Error: Required tables ('image_clusters' and 'images') missing from database.")
        print("[*] Please run 'run_evoc_ovis.bat' first to generate EVoC cluster assignments.")
        sqlite_database_connection.close()
        sys.exit(1)

    # WHAT: Creating image_cluster_topics destination table.
    # WHY: Persists semantic cluster names so Scope Map can render cluster labels on canvas.
    sqlite_database_cursor.execute('''
        CREATE TABLE IF NOT EXISTS image_cluster_topics (
            cluster_label INTEGER PRIMARY KEY,
            topic_title TEXT NOT NULL,
            keyphrases_json TEXT NOT NULL,
            sample_size INTEGER NOT NULL,
            extraction_engine TEXT NOT NULL,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    ''')

    # WHAT: Fetching distinct cluster assignments and sample sizes.
    # WHY: We exclude cluster -1 (unclustered noise) from thematic naming.
    sqlite_database_cursor.execute('''
        SELECT cluster_label, COUNT(*) as cluster_item_count
        FROM image_clusters
        WHERE cluster_label != -1
        GROUP BY cluster_label
        ORDER BY cluster_label ASC
    ''')
    discovered_clusters_statistics_collection = sqlite_database_cursor.fetchall()
    print(f"[*] Found {len(discovered_clusters_statistics_collection)} distinct EVoC visual clusters to label.")

    start_timestamp_seconds = time.time()
    labeled_clusters_count = 0

    for single_cluster_label, cluster_item_count in discovered_clusters_statistics_collection:
        # WHAT: Fetching image summaries and tags for members of this cluster.
        # WHY: Toponymy analyzes visible text tokens to determine shared semantic traits.
        sqlite_database_cursor.execute('''
            SELECT images.analysis
            FROM images
            JOIN image_clusters ON images.id = image_clusters.image_id
            WHERE image_clusters.cluster_label = ?
            LIMIT ?
        ''', (single_cluster_label, maximum_samples_per_cluster_count))

        sampled_image_rows = sqlite_database_cursor.fetchall()
        text_corpus_documents_list = []

        for single_image_row in sampled_image_rows:
            raw_analysis_payload = single_image_row[0]
            if not raw_analysis_payload:
                continue

            try:
                parsed_analysis_dictionary = (
                    json.loads(raw_analysis_payload)
                    if isinstance(raw_analysis_payload, str)
                    else raw_analysis_payload
                )

                summary_text = parsed_analysis_dictionary.get('summary', '')
                tags_list = parsed_analysis_dictionary.get('tags', [])
                objects_list = parsed_analysis_dictionary.get('objects', [])

                combined_document_text = f"{summary_text} {' '.join(tags_list)} {' '.join(objects_list)}"
                if combined_document_text.strip():
                    text_corpus_documents_list.append(combined_document_text.strip())
            except Exception:
                continue

        # Extract top keyphrases via Toponymy
        extracted_toponymy_keyphrases_list = extract_keyphrases_from_text_collection(
            text_corpus_documents_list,
            maximum_keyphrases_to_extract_count=maximum_keyphrases_per_cluster_count
        )

        formatted_topic_title_string = format_human_readable_topic_title(extracted_toponymy_keyphrases_list)

        # WHAT: Inserting or replacing cluster topic record in SQLite.
        # WHY: Guarantees latest extracted topic titles are preserved across re-runs.
        sqlite_database_cursor.execute('''
            INSERT OR REPLACE INTO image_cluster_topics (
                cluster_label,
                topic_title,
                keyphrases_json,
                sample_size,
                extraction_engine,
                updated_at
            ) VALUES (?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
        ''', (
            single_cluster_label,
            formatted_topic_title_string,
            json.dumps(extracted_toponymy_keyphrases_list),
            len(text_corpus_documents_list),
            'toponymy' if IS_TOPONYMY_LIBRARY_AVAILABLE else 'frequency_fallback'
        ))

        labeled_clusters_count += 1
        print(f"  [Cluster {single_cluster_label:>2}] ({cluster_item_count:>4} images) -> \"{formatted_topic_title_string}\" | Keyphrases: {', '.join(extracted_toponymy_keyphrases_list)}")

    sqlite_database_connection.commit()
    sqlite_database_connection.close()

    elapsed_duration_seconds = time.time() - start_timestamp_seconds
    print("----------------------------------------------------------------------")
    print(f"[*] Successfully labeled {labeled_clusters_count} clusters in {elapsed_duration_seconds:.2f}s!")
    print("[*] Saved results to table 'image_cluster_topics' in images.db.")
    print("======================================================================")


if __name__ == "__main__":
    execute_toponymy_cluster_labeling_pipeline()

